set local session_replication_role = replica;
update public.af_movimientos m set created_at = r.revisado_en from public.af_reportes r, public.af_fincas f where m.reporte_id = r.id and r.revisado_en is not null and f.id = m.finca_id and f.nombre = 'IYOMA PRUEBAS';
update public.af_movimientos m set created_at = (m.fecha + time '09:00' + (abs(hashtext(m.id::text)) % 480) * interval '1 minute') at time zone 'America/Bogota' from public.af_fincas f where m.reporte_id is null and f.id = m.finca_id and f.nombre = 'IYOMA PRUEBAS';
set local session_replication_role = origin;
update public.af_labores l set costo_unitario_plan = v.tarifa, costo_aparte_unitario_plan = v.aparte, pasadas_plan = v.pasadas, editado_por = 'U005' from (values ('ROTURACIÓN', 225000, 0, 1), ('FERTILIZACIÓN', 160000, 2490000, 1), ('CONTROL DE MALEZAS', 120000, 980000, 3), ('RIEGO', 0, 125000, 8)) as v(labor, tarifa, aparte, pasadas), public.af_ciclos c, public.af_suertes s, public.af_fincas f where l.labor = v.labor and c.id = l.ciclo_id and c.estado = 'ABIERTO' and s.id = c.suerte_id and f.id = s.finca_id and f.nombre = 'IYOMA PRUEBAS';
select set_config('af.via_funcion','1',true);
